from __future__ import annotations

from typing import Any

from orders.application.errors import CustomerNotFound
from orders.application.order_service import OrderService
from orders.controllers.http import InvalidRequest, Response, bad_request, not_found, require_positive_int
from orders.domain.orders import OrderSummary


def history_entry(summary: OrderSummary) -> dict[str, Any]:
    return {"order_id": summary.order.order_id, "status": summary.order.status,
            "total_cents": summary.total_cents}


class CustomerInsightsController:
    def __init__(self, service: OrderService) -> None:
        self._service = service

    def handle_order_history(self, customer_id: str) -> Response:
        try:
            summaries = self._service.order_history(customer_id)
        except CustomerNotFound:
            return not_found("customer")
        return Response(200, {"customer_id": customer_id,
                              "orders": [history_entry(s) for s in summaries]})

    def handle_lifetime_value(self, customer_id: str) -> Response:
        try:
            value = self._service.lifetime_value(customer_id)
        except CustomerNotFound:
            return not_found("customer")
        return Response(200, {"customer_id": customer_id, "order_count": value.order_count,
                              "lifetime_value_cents": value.lifetime_value_cents})

def order(api, customer_id, *items):
    return api.orders.handle_create({"customer_id": customer_id,
                                     "items": [{"sku": s, "quantity": q} for s, q in items]})


def test_unknown_customer_is_404(shop):
    response = shop.insights.handle_order_history("nobody")
    assert response.status == 404
    assert response.body == {"error": "customer not found"}


def test_customer_with_no_orders_gets_empty_list(shop):
    response = shop.insights.handle_order_history("c1")
    assert response.status == 200
    assert response.body == {"customer_id": "c1", "orders": []}


def test_history_is_newest_first_and_only_for_that_customer(shop):
    first = order(shop, "c1", ("BOOK", 1)).body["order_id"]
    order(shop, "c2", ("PEN", 1))
    second = order(shop, "c1", ("PEN", 2)).body["order_id"]
    body = shop.insights.handle_order_history("c1").body
    assert [o["order_id"] for o in body["orders"]] == [second, first]


def test_entries_have_status_and_summary_total_including_discount(shop):
    oid = order(shop, "c2", ("LAMP", 2)).body["order_id"]
    summary = shop.orders.handle_get(oid).body
    body = shop.insights.handle_order_history("c2").body
    assert body["orders"] == [{"order_id": oid, "status": "placed",
                               "total_cents": summary["total_cents"]}]
    assert body["orders"][0]["total_cents"] == 10200


def test_lifetime_value_unknown_customer_is_404(shop):
    response = shop.insights.handle_lifetime_value("nobody")
    assert response.status == 404
    assert response.body == {"error": "customer not found"}


def test_lifetime_value_with_no_orders_is_zero(shop):
    response = shop.insights.handle_lifetime_value("c1")
    assert response.status == 200
    assert response.body == {"customer_id": "c1", "order_count": 0, "lifetime_value_cents": 0}


def test_lifetime_value_sums_totals_including_discount_and_skips_cancelled(shop):
    order(shop, "c2", ("LAMP", 2))            # 12000 - 15% = 10200
    order(shop, "c2", ("BOOK", 1))            # 2500, below threshold
    cancelled = order(shop, "c2", ("PEN", 1)).body["order_id"]
    shop.orders.handle_cancel(cancelled)
    order(shop, "c1", ("PEN", 1))             # other customer, excluded
    response = shop.insights.handle_lifetime_value("c2")
    assert response.status == 200
    assert response.body == {"customer_id": "c2", "order_count": 2, "lifetime_value_cents": 12700}


def test_cancelled_orders_are_included_with_status(shop):
    kept = order(shop, "c1", ("BOOK", 1)).body["order_id"]
    cancelled = order(shop, "c1", ("PEN", 1)).body["order_id"]
    shop.orders.handle_cancel(cancelled)
    body = shop.insights.handle_order_history("c1").body
    assert body["orders"] == [
        {"order_id": cancelled, "status": "cancelled", "total_cents": 300},
        {"order_id": kept, "status": "placed", "total_cents": 2500},
    ]

